function sortByField(rows, field) {
    out = rows.copy();
    i = 0;
    while i < len(out) {
        best = i;
        j = i + 1;
        while j < len(out) {
            if out[j][field] < out[best][field] { best = j; }
            j++;
        }
        if best != i { t = out[i]; out[i] = out[best]; out[best] = t; }
        i++;
    }
    return out;
}
