function validPassword(p) {
    if len(p) < 8 { return false; }
    hasDigit = false; hasAlpha = false;
    foreach c in p {
        if c >= "0" and c <= "9" { hasDigit = true; }
        elseif c.lower() != c.upper() { hasAlpha = true; }
    }
    return hasDigit and hasAlpha;
}
print(validPassword("abc12345"), validPassword("abcdefgh"), validPassword("12345678"));

function roman(n) {
    vals = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1];
    syms = ["M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"];
    out = "";
    i = 0;
    while n > 0 {
        while n >= vals[i] { out += syms[i]; n -= vals[i]; }
        i++;
    }
    return out;
}
print(roman(2026), roman(9), roman(44));

function transpose(m) {
    cols = len(m[0]);
    return [[row[c] for row in m] for c in range(cols)];
}
