function caesar(text, shift) {
    out = "";
    foreach c in text {
        if c.lower() != c.upper() {
            base = c == c.upper() ? 65 : 97;
            out += chr((ord(c) - base + shift) % 26 + base);
        } else {
            out += c;
        }
    }
    return out;
}
print(caesar("Hello, PyHP!", 3));

